package com.aaliyun.leadnews.wemedia.config;
import com.aaliyun.leadnews.model.ai.WmNewsAuditRequestedEvent;import org.apache.kafka.common.TopicPartition;import org.springframework.context.annotation.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.*;import org.springframework.kafka.support.ExponentialBackOffWithMaxRetries;
@Configuration public class AuditKafkaConfiguration {@Bean DefaultErrorHandler auditKafkaErrorHandler(KafkaTemplate<String,WmNewsAuditRequestedEvent> template,AuditProperties p){DeadLetterPublishingRecoverer recoverer=new DeadLetterPublishingRecoverer(template,(r,e)->new TopicPartition(p.kafka().dltTopic(),r.partition()));ExponentialBackOffWithMaxRetries backoff=new ExponentialBackOffWithMaxRetries(2);backoff.setInitialInterval(1000);backoff.setMultiplier(1);backoff.setMaxInterval(1000);return new DefaultErrorHandler(recoverer,backoff);}}
